/** CSS variable for a semantic token path, e.g. v('text.muted') → var(--bp-text-muted). */
export function v(path: string): string {
  return `var(--bp-${path.split('.').map((s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()).join('-')})`;
}
